Local Ltac pf_finish p' E' g' n1 n2 v1 v2 bsz bb :=
  apply evt_done; unfold pf_post, oPP, oNM, oVL, oBF, PfTab, PF_TABPTR, PF_TAB;
  do 16 eexists; exists p', E', g', n1, n2, v1, v2, bsz, bb;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

